[DataContractAttribute]
class TFMDrawFlowLogicBlockContract
{
    int                                 id;
    Name                                name;
    TFMDrawFlowLogicBlockDataContract   data;
    str                                 html;
    str                                 cssClass;
    real                                posY;
    real                                posX;
    Map                                 inputs;
    Map                                 outputs;


}

Method.Source:
public void new()
{
    inputs = new Map(Types::String, Types::Class);
    outputs = new Map(Types::String, Types::Class);
    cssClass = 'LogicBlock';
}

public str nextOutput()
{
    int counter = 1;
    TFMDrawFlowLogicBlockInputsOutputs innerMap;

    while (outputs.exists('output_' + int2Str(counter)))
    {
        innerMap = outputs.lookup('output_' + int2Str(counter));

        if (!innerMap.parmConnection().elements())
        {
            return 'output_' + int2Str(counter);
        }

        counter++;
    }
    return 'output_' + int2Str(counter);
}

[DataMemberAttribute('id')]
public int parmId(int _id = id)
{
    id = _id;
    return id;
}

[DataMemberAttribute('pos_x')]
public real parmPosX(real _posX = posX)
{
    posX = _posX;
    return posX;
}

[DataMemberAttribute('pos_y')]
public real parmPosY(real _posY = posY)
{
    posY = _posY;
    return posY;
}

[DataMemberAttribute('name')]
public Name parmName(Name _name = name)
{
    name = _name;
    return name ? name : 'LogicBlock';
}

[DataMemberAttribute('data')]
public TFMDrawFlowLogicBlockDataContract parmData(TFMDrawFlowLogicBlockDataContract _data = data)
{
    data = _data;
    return data;
}

[DataMemberAttribute('inputs'), TFMContractClass(classStr(TFMDrawFlowLogicBlockInputsOutputs))]
public Map parmInputs(Map _inputs = inputs)
{
    inputs = _inputs;
    return inputs;
}

[DataMemberAttribute('outputs'), TFMContractClass(classStr(TFMDrawFlowLogicBlockInputsOutputs))]
